(() => {
  'use strict';
  const DATA = window.BIBLE_DATA;
  const KEY = 'e-journal-bible-v1';
  const DEFAULTS = {
    name: '', page: 'home', reader: { book: 'John', chapter: 3, selectedVerse: 16 },
    notes: {}, highlights: {}, bookmarks: [], favorites: [], annotations: {}, journal: [], prayers: [],
    reading: { plan: null, day: 1, completed: [], chaptersRead: [], paused: false, history: [] },
    memory: [], goals: [], studyBoards: [], currentBoardId: null,
    preferences: { theme: 'light', fontSize: 19, lineHeight: 1.86, readingWidth: 'comfortable', reminder: '', translation: 'KJV' }
  };
  const clone = x => JSON.parse(JSON.stringify(x));
  let state = loadState();
  let searchQuery = '';
  let sideTab = 'note';
  let annotating = false, annotationTool = 'pen', annotationColor = '#caa94f', annotationWidth = 3;
  let redoStrokes = [];
  let boardTextDraft = '';
  let toastTimer;
  const plans = [
    { id: 'john', title: 'Walk through John', subtitle: 'A closer look at the life and words of Jesus.', days: 2, references: ['John 1', 'John 3'] },
    { id: 'psalms', title: 'Psalms for the soul', subtitle: 'Two prayers for reflection and trust.', days: 2, references: ['Psalms 23', 'Psalms 46'] },
    { id: 'proverbs', title: 'Wisdom for today', subtitle: 'A quiet reading from Proverbs 3.', days: 1, references: ['Proverbs 3'] },
    { id: 'steady', title: 'A steady beginning', subtitle: 'Seven gentle days of reading and reflection.', days: 7, references: ['Genesis 1', 'Psalms 23', 'Matthew 5', 'John 3', 'Romans 8', 'Philippians 4', '1 John 4'] }
  ];
  const prompts = ['What stood out to you in this passage?', 'What is this passage teaching you?', 'How might you carry this with you today?', 'What are you currently praying about?', 'What is one thing you want to remember?'];
  const $ = (sel, root = document) => root.querySelector(sel);
  const $$ = (sel, root = document) => [...root.querySelectorAll(sel)];
  const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  const uid = () => `${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`;
  const dateKey = (d = new Date()) => { const x = new Date(d); return `${x.getFullYear()}-${String(x.getMonth()+1).padStart(2,'0')}-${String(x.getDate()).padStart(2,'0')}`; };
  const dateLabel = (v, opts = { month: 'long', day: 'numeric', year: 'numeric' }) => { const d = new Date(`${v || dateKey()}T12:00:00`); return Number.isNaN(+d) ? '' : d.toLocaleDateString(undefined, opts); };
  const passageKey = (book = state.reader.book, chapter = state.reader.chapter) => `${state.preferences.translation}|${book}|${chapter}`;
  const refFor = (book, chapter, verse) => `${book} ${chapter}:${verse}`;
  const verseText = (book, chapter, verse) => DATA.books[book]?.chapters[chapter]?.[verse - 1] || '';
  const currentChapter = () => DATA.books[state.reader.book]?.chapters[state.reader.chapter] || [];
  const chaptersFor = book => Object.keys(DATA.books[book]?.chapters || {}).map(Number).sort((a,b)=>a-b);
  const books = Object.keys(DATA.books);
  const knownRefs = () => Object.entries(DATA.books).flatMap(([book, val]) => Object.entries(val.chapters).flatMap(([chapter, verses]) => verses.map((_, i) => ({ book, chapter: Number(chapter), verse: i + 1 }))));

  function loadState() {
    try {
      const saved = JSON.parse(localStorage.getItem(KEY) || 'null');
      if (!saved || typeof saved !== 'object') return clone(DEFAULTS);
      const value = { ...clone(DEFAULTS), ...saved };
      value.reader = { ...DEFAULTS.reader, ...(saved.reader || {}) };
      value.preferences = { ...DEFAULTS.preferences, ...(saved.preferences || {}) };
      value.reading = { ...DEFAULTS.reading, ...(saved.reading || {}) };
      if (!Array.isArray(value.reading.chaptersRead)) value.reading.chaptersRead = [];
      for (const k of ['bookmarks','favorites','journal','prayers','memory','goals','studyBoards']) if (!Array.isArray(value[k])) value[k] = [];
      for (const k of ['notes','highlights','annotations']) if (!value[k] || typeof value[k] !== 'object') value[k] = {};
      if (!DATA.books[value.reader.book] || !DATA.books[value.reader.book].chapters[value.reader.chapter]) { value.reader.book='John'; value.reader.chapter=3; }
      return value;
    } catch { return clone(DEFAULTS); }
  }
  function persist() {
    try { localStorage.setItem(KEY, JSON.stringify(state)); applyPreferences(); }
    catch { toast('Storage is full. Export your data and remove older drawings to make room.'); }
  }
  function applyPreferences() {
    document.body.classList.toggle('theme-dark', state.preferences.theme === 'dark');
    document.documentElement.style.setProperty('--reader-size', `${Number(state.preferences.fontSize) || 19}px`);
    document.documentElement.style.setProperty('--line-height', String(Number(state.preferences.lineHeight) || 1.86));
  }
  function toast(message) {
    const el = $('#toast'); el.textContent = message; el.classList.add('show'); clearTimeout(toastTimer); toastTimer = setTimeout(() => el.classList.remove('show'), 2600);
  }
  function setPage(page) {
    if (page === 'more') { openMore(); return; }
    const valid = ['home','bible','journal','prayer','plans','mybible','study','settings'];
    if (!valid.includes(page)) page = 'home';
    state.page = page; persist();
    $$('.page').forEach(el => el.classList.toggle('active', el.dataset.page === page));
    $$('.nav-item,.mobile-nav button').forEach(el => el.classList.toggle('active', el.dataset.page === page));
    $('#top-title').textContent = ({ home:'Home', bible:'Bible', journal:'Journal', prayer:'Prayer journal', plans:'Reading plans', mybible:'My Bible', study:'Study space', settings:'Settings' })[page];
    $('#top-crumb').textContent = page === 'bible' ? 'READ & REFLECT' : page === 'home' ? 'YOUR QUIET PLACE' : 'YOUR PERSONAL SPACE';
    $('#sidebar').classList.remove('open');
    renderCurrent();
    window.scrollTo({ top: 0, behavior: 'smooth' });
  }
  function renderCurrent() {
    const fn = { home:renderHome, bible:renderBible, journal:renderJournal, prayer:renderPrayer, plans:renderPlans, mybible:renderMyBible, study:renderStudy, settings:renderSettings }[state.page];
    if (fn) fn();
  }
  function renderHome() {
    const h = new Date().getHours(); const greeting = h < 12 ? 'Good morning' : h < 17 ? 'Good afternoon' : 'Good evening';
    const daily = dailyReference(); const totalEntries = state.journal.length;
    const completedChapters = state.reading.chaptersRead.length;
    const plan = plans.find(p => p.id === state.reading.plan);
    const pct = plan ? Math.min(100, Math.round((state.reading.completed.length / plan.days) * 100)) : 0;
    const totalSampleChapters = books.reduce((sum, book) => sum + chaptersFor(book).length, 0);
    const readProgress = totalSampleChapters ? Math.min(100, Math.round(completedChapters / totalSampleChapters * 100)) : 0;
    const recent = [...state.journal].sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt)).slice(0,3);
    const highlightPreview = miniVerseList(Object.entries(state.highlights).slice(-3).reverse().map(([ref,color])=>({ref,color})), 'Highlighted verses will appear here.');
    const favoritePreview = miniVerseList(state.favorites.slice(-3).reverse().map(ref=>({ref})), 'Save a verse as a favorite while reading.');
    const recentHtml = recent.length ? recent.map(entry => `<div class="entry-row"><div class="entry-date"><strong>${new Date(`${entry.date}T12:00:00`).getDate()}</strong>${new Date(`${entry.date}T12:00:00`).toLocaleDateString(undefined,{month:'short'}).toUpperCase()}</div><div><h4>${esc(entry.title || 'Untitled reflection')}</h4><p>${esc(entry.reference || entry.type || 'Journal')} · ${esc((entry.content || entry.observation || '').slice(0,74))}${(entry.content || entry.observation || '').length>74?'…':''}</p></div></div>`).join('') : `<div class="empty-state"><strong>Your journal starts here</strong>Save a thought alongside today's reading.</div>`;
    const verse = verseText(daily.book,daily.chapter,daily.verse);
    $('#page-home').innerHTML = `<div class="welcome-line">${greeting}${state.name ? `, ${esc(state.name)}` : ''}. Take a breath and settle in.</div><h1>A little time in the Word.</h1><p class="page-subtitle">A quiet space to read, reflect, and keep what matters close.</p>
      <div class="hero-grid"><article class="daily-card"><span class="eyebrow">TODAY'S VERSE · ${esc(DATA.translation)}</span><blockquote>“${esc(verse)}”</blockquote><div class="daily-ref">${esc(refFor(daily.book,daily.chapter,daily.verse).toUpperCase())}</div><div class="btn-row"><button class="btn" data-action="read-ref" data-ref="${esc(refFor(daily.book,daily.chapter,daily.verse))}">Read in context <span>↗</span></button><button class="btn secondary" data-action="journal-ref" data-ref="${esc(refFor(daily.book,daily.chapter,daily.verse))}">Journal about this</button><button class="icon-button" title="Save verse" aria-label="Save daily verse" data-action="favorite-ref" data-ref="${esc(refFor(daily.book,daily.chapter,daily.verse))}">♡</button></div></article>
      <article class="card continue-card"><div class="continue-head"><span class="eyebrow">CONTINUE READING</span><span class="book-glyph">▤</span></div><h2>${esc(state.reader.book)}</h2><div class="chapter-label">Chapter ${state.reader.chapter} · ${completedChapters ? `${completedChapters} chapters marked complete` : 'Pick up where you left off'}</div><div class="progress-track"><span style="width:${Math.min(100,readProgress)}%"></span></div><div class="continue-foot"><span>${completedChapters} read · ${readProgress}% of included chapters</span><button class="btn small" data-action="continue-reading">Open Bible&nbsp; →</button></div></article></div>
      <div class="section-heading"><h2>Your rhythm</h2><button class="text-link" data-page="mybible">View your progress →</button></div><div class="metric-grid"><div class="card metric"><div class="metric-label">Chapters read <span class="metric-icon">▤</span></div><strong>${completedChapters}</strong></div><div class="card metric"><div class="metric-label">Journal entries <span class="metric-icon">✎</span></div><strong>${totalEntries}</strong></div><div class="card metric"><div class="metric-label">Verses highlighted <span class="metric-icon">✦</span></div><strong>${Object.keys(state.highlights).length}</strong></div><div class="card metric"><div class="metric-label">Prayer requests <span class="metric-icon">♡</span></div><strong>${state.prayers.length}</strong></div></div>
      <div class="section-heading"><h2>Keep close</h2><button class="text-link" data-page="journal">Open journal →</button></div><div class="home-lower"><article class="panel"><div class="section-heading" style="margin:0 0 7px"><h3>Recent reflections</h3><button class="text-link" data-action="new-journal">＋ Write</button></div>${recentHtml}</article><article class="panel"><span class="eyebrow">YOUR READING PLAN</span>${plan ? `<div class="plan-mini" style="margin-top:12px"><strong>${esc(plan.title)}</strong><p>Day ${Math.min(state.reading.day,plan.days)} of ${plan.days}${state.reading.paused?' · Paused':''}</p><div class="progress-track"><span style="width:${pct}%"></span></div><button class="btn small" data-action="continue-plan">Continue reading</button></div>` : `<div class="plan-mini" style="margin-top:12px"><strong>Make a gentle reading rhythm</strong><p>Choose a plan that fits the season you're in.</p><button class="btn small secondary" data-page="plans">Browse reading plans</button></div>`}<div class="btn-row" style="margin-top:12px"><button class="btn small secondary" data-page="prayer">Open prayer journal</button><button class="btn small secondary" data-page="study">Study canvas</button></div></article></div><div class="section-heading"><h2>Verses you've kept</h2><button class="text-link" data-page="mybible">Open My Bible →</button></div><div class="home-lower"><article class="panel"><span class="eyebrow">RECENT HIGHLIGHTS</span>${highlightPreview}</article><article class="panel"><span class="eyebrow">FAVORITE VERSES</span>${favoritePreview}</article></div>`;
  }
  function dailyReference() {
    const options = [{book:'John',chapter:3,verse:16},{book:'Psalms',chapter:23,verse:1},{book:'Romans',chapter:8,verse:28},{book:'Philippians',chapter:4,verse:6},{book:'1 John',chapter:4,verse:19},{book:'Proverbs',chapter:3,verse:5}];
    const start = new Date(new Date().getFullYear(),0,0); const doy = Math.floor((Date.now()-start)/86400000); return options[doy % options.length];
  }
  function miniVerseList(records, emptyMessage) {
    if (!records.length) return `<p class="tiny" style="margin-top:13px">${esc(emptyMessage)}</p>`;
    return `<div class="related-list" style="margin-top:12px">${records.map(item=>{const p=parseReference(item.ref);return `<button class="related-item" style="text-align:left;border:0;width:100%" data-action="read-ref" data-ref="${esc(item.ref)}">${item.color?`<span class="highlight-dot" style="background:${esc(item.color)};margin-right:7px"></span>`:''}<strong>${esc(item.ref)}</strong>${esc(p?verseText(p.book,p.chapter,p.verse):'')}</button>`;}).join('')}</div>`;
  }
  function renderBible() {
    const {book,chapter,selectedVerse} = state.reader; const verses = currentChapter();
    const selected = Math.max(1,Math.min(selectedVerse || 1,verses.length)); state.reader.selectedVerse = selected;
    const ref = refFor(book,chapter,selected); const highlight = state.highlights[ref];
    const selectedText = verseText(book,chapter,selected); const note = state.notes[ref];
    const chapters = chaptersFor(book); const overview = DATA.overviews[book];
    const verseHtml = verses.map((text,i)=>{
      const n=i+1, vr=refFor(book,chapter,n), col=state.highlights[vr];
      const style = col ? `background:${esc(col)}38;box-shadow:inset 0 -2px ${esc(col)};` : '';
      return `<div class="verse-row ${n===selected?'selected':''}" style="${style}" data-action="select-verse" data-verse="${n}" tabindex="0" role="button" aria-label="${esc(vr)} ${esc(text)}"><span class="verse-number">${n}</span><span class="verse-text">${esc(text)}${state.notes[vr]?'<span class="verse-note-mark" title="Personal note">✎</span>':''}${state.bookmarks.includes(vr)?'<span class="verse-flag" title="Bookmarked">🔖</span>':''}</span></div>`;
    }).join('');
    const annotationKey = passageKey(book,chapter);
    const side = sideTab === 'note' ? `<div class="quick-prompt"><span class="eyebrow">A NOTE ON ${esc(ref.toUpperCase())}</span><p>${note ? 'Your thought, kept with this verse.' : 'What would you like to remember about this verse?'}</p></div><textarea class="text-area" id="quick-note" aria-label="Note for ${esc(ref)}" placeholder="Write a thought, question, or connection…">${esc(note?.text || '')}</textarea><div class="btn-row" style="margin-top:9px"><button class="btn small" data-action="save-quick-note" data-ref="${esc(ref)}">${note?'Update note':'Save note'}</button><button class="btn small secondary" data-action="journal-ref" data-ref="${esc(ref)}">Open journal</button></div>` : sideTab === 'related' ? `<span class="eyebrow">RELATED SCRIPTURE</span><p class="scope-note" style="margin:8px 0 12px">A small hand-curated set for reflection. Open any passage in context.</p><div class="related-list">${relatedFor(ref).map(r=>`<div class="related-item" data-action="read-ref" data-ref="${esc(r.ref)}"><strong>${esc(r.ref)}</strong>${esc(r.text)}</div>`).join('') || '<div class="empty-state">No related passages are listed for this verse yet.</div>'}</div>` : `<span class="eyebrow">CHAPTER NOTES</span><p class="scope-note">Keep a thought connected to ${esc(book)} ${chapter}.</p><textarea class="text-area" id="chapter-note" aria-label="Chapter note" placeholder="What is on your mind about this chapter?">${esc(state.notes[`${book} ${chapter}`]?.text || '')}</textarea><button class="btn small" style="margin-top:9px" data-action="save-chapter-note" data-ref="${esc(`${book} ${chapter}`)}">Save chapter note</button>`;
    const annotationTools = annotating ? `<div class="annotation-tools"><button class="btn small ${annotationTool==='pen'?'':'secondary'}" data-action="annotation-tool" data-tool="pen">Pen</button><button class="btn small ${annotationTool==='highlighter'?'':'secondary'}" data-action="annotation-tool" data-tool="highlighter">Highlighter</button><button class="btn small ${annotationTool==='eraser'?'':'secondary'}" data-action="annotation-tool" data-tool="eraser">Eraser</button><input type="color" id="annotation-color" value="${esc(annotationColor)}" aria-label="Ink color"><label for="annotation-width">Size</label><input id="annotation-width" type="range" min="1" max="14" value="${annotationWidth}" aria-label="Stroke size"><button class="icon-button" data-action="undo-annotation" title="Undo">↶</button><button class="icon-button" data-action="redo-annotation" title="Redo">↷</button><button class="icon-button" data-action="clear-annotation" title="Clear this page">⌫</button><button class="btn small secondary" data-action="toggle-annotate">Done</button></div>` : '';
    $('#page-bible').innerHTML = `<div class="reader-heading"><div><span class="eyebrow">YOUR PERSONAL STUDY BIBLE</span><h1>${esc(book)} ${chapter}</h1><p class="page-subtitle">Read slowly. Let a verse stay with you.</p></div><div class="btn-row"><button class="btn secondary" data-action="chapter-reflection">✎ What stood out to me?</button><button class="btn" data-action="chapter-complete">Mark chapter read ✓</button></div></div>
      <div class="panel reader-controls"><label class="tiny" for="book-select">BOOK</label><select class="control-select" id="book-select">${books.map(b=>`<option ${b===book?'selected':''}>${esc(b)}</option>`).join('')}</select><label class="tiny" for="chapter-select">CHAPTER</label><select class="control-select" id="chapter-select">${chapters.map(c=>`<option value="${c}" ${c===Number(chapter)?'selected':''}>${c}</option>`).join('')}</select><label class="tiny" for="translation-select">VERSION</label><select class="control-select translation" id="translation-select"><option>KJV</option></select><div class="reader-tools"><label for="font-size">A</label><input id="font-size" type="range" min="16" max="25" value="${Number(state.preferences.fontSize)||19}" aria-label="Reading font size"><button class="icon-button" data-action="toggle-annotate" title="Write on this page">✎</button><button class="icon-button" data-action="search-open" title="Search Scripture">⌕</button></div></div>
      <div class="reader-layout"><article class="panel scripture-panel" id="scripture-panel"><canvas id="annotation-canvas" class="draw-surface ${annotating?'enabled':''}" aria-label="Handwritten annotation layer"></canvas><div class="scripture-top"><div><span class="eyebrow">KING JAMES VERSION</span><h2>${esc(book).toUpperCase()} <span style="font-size:12px;color:#918e82">${chapter}</span></h2></div><span class="chapter-mark">${chapter}</span></div>${overview?`<div class="overview-chip"><strong>About this book</strong> · ${esc(overview[0])}<br><span style="font-size:10px">Themes: ${esc(overview[1])}</span></div>`:''}<div class="verse-list" id="verse-list">${verseHtml}</div><div class="context-tools"><span class="context-label">Selected · ${esc(ref)}</span><button class="icon-button" data-action="highlight" title="Highlight">▰</button><button class="icon-button" data-action="bookmark" title="Bookmark">🔖</button><button class="icon-button" data-action="favorite" title="Favorite">♡</button><button class="icon-button" data-action="note" title="Add note">✎</button><button class="icon-button" data-action="copy" title="Copy verse">▢</button><button class="icon-button" data-action="share" title="Share verse">↗</button><button class="icon-button" data-action="study-add-ref" title="Add to study canvas">✧</button></div>${annotationTools}<div class="highlight-legend"><span class="tiny">HIGHLIGHTS</span><button class="highlight-dot" style="background:#f2d77b" title="Important" data-action="highlight-color" data-color="#f2d77b"></button><button class="highlight-dot" style="background:#a9c8df" title="Prayer" data-action="highlight-color" data-color="#a9c8df"></button><button class="highlight-dot" style="background:#bdd2a5" title="Promise" data-action="highlight-color" data-color="#bdd2a5"></button><button class="highlight-dot" style="background:#e7b9b5" title="Reflection" data-action="highlight-color" data-color="#e7b9b5"></button><button class="highlight-dot" style="background:#c6b3d4" title="Favorite" data-action="highlight-color" data-color="#c6b3d4"></button><span class="tiny">Choose a color with a verse selected</span></div><div class="reader-caption">Scripture sample: King James Version (public domain). This edition includes selected portions of chapters; use the data layer to add a complete, properly licensed translation. Your annotations are saved on this device.</div><div class="reader-nav"><button class="btn small secondary" data-action="chapter-prev">← Previous available chapter</button><button class="btn small secondary" data-action="chapter-next">Next available chapter →</button></div></article>
      <aside class="panel journal-side"><div class="journal-side-head"><h3>Stay with the Word</h3><span class="tiny">${esc(ref)}</span></div><div class="side-tabs"><button class="side-tab ${sideTab==='note'?'active':''}" data-action="side-tab" data-tab="note">Verse note</button><button class="side-tab ${sideTab==='related'?'active':''}" data-action="side-tab" data-tab="related">Related</button><button class="side-tab ${sideTab==='chapter'?'active':''}" data-action="side-tab" data-tab="chapter">Chapter</button></div>${side}<div class="scope-note" style="margin-top:16px">Your notes, highlights, and drawings stay in this browser. Export a backup in Settings.</div></aside></div>`;
    bindCanvas(annotationKey);
    updateReaderNav(book,chapter);
  }
  function relatedFor(ref) {
    const mapping = {
      'John 3:16': [['Romans 5:8','God commendeth his love toward us.'],['1 John 4:9','In this was manifested the love of God toward us.'],['Ephesians 2:4','God, who is rich in mercy, for his great love wherewith he loved us.']],
      'Psalms 23:1': [['John 10:11','I am the good shepherd: the good shepherd giveth his life for the sheep.'],['Isaiah 40:11','He shall feed his flock like a shepherd.']],
      'Philippians 4:6': [['1 Peter 5:7','Casting all your care upon him; for he careth for you.']],
      'Romans 8:28': [['Genesis 50:20','Ye thought evil against me; but God meant it unto good.']],
      '1 John 4:19': [['John 13:34','That ye love one another; as I have loved you.']]
    };
    return (mapping[ref] || []).map(([r,text])=>({ref:r,text}));
  }
  function updateReaderNav(book,chapter) { const pairs=knownRefs().map(x=>`${x.book}|${x.chapter}`).filter((x,i,a)=>a.indexOf(x)===i); const idx=pairs.indexOf(`${book}|${chapter}`); $('#page-bible [data-action="chapter-prev"]')?.toggleAttribute('disabled',idx<=0); $('#page-bible [data-action="chapter-next"]')?.toggleAttribute('disabled',idx<0||idx>=pairs.length-1); }
  function goToReference(ref) {
    const parsed=parseReference(ref);
    if (!parsed) { toast('That reference is not in the included KJV sample.'); return; }
    state.reader={book:parsed.book,chapter:parsed.chapter,selectedVerse:parsed.verse||1}; setPage('bible');
    setTimeout(()=>{ const row=$(`[data-verse="${state.reader.selectedVerse}"]`); row?.scrollIntoView({behavior:'smooth',block:'center'}); },100);
  }
  function parseReference(input) {
    const s=String(input).trim().replace(/[–—]/g,'-');
    let m=s.match(/^(.+?)\s+(\d+)(?::(\d+))?(?:\s*[-–]\s*\d+)?$/);
    if(!m) return null; const book=books.find(b=>b.toLowerCase()===m[1].trim().toLowerCase()); if(!book) return null;
    const chapter=Number(m[2]), verse=Number(m[3]||1); if(!DATA.books[book].chapters[chapter]||verse<1||verse>DATA.books[book].chapters[chapter].length) return null;
    return {book,chapter,verse};
  }
  function currentRef() { return refFor(state.reader.book,state.reader.chapter,state.reader.selectedVerse||1); }
  function highlight(ref=currentRef(), color='#f2d77b') { if(state.highlights[ref]) delete state.highlights[ref]; else state.highlights[ref]=color; persist(); renderBible(); }
  function toggleSaved(kind,ref=currentRef()) { const arr=state[kind]; const idx=arr.indexOf(ref); idx<0?arr.push(ref):arr.splice(idx,1); persist(); renderCurrent(); toast(idx<0?(kind==='bookmarks'?'Bookmark saved':'Verse saved to My Bible'):'Removed from My Bible'); }
  function openNoteModal(ref) {
    const old=state.notes[ref]; openModal(`<span class="eyebrow">KEEP A THOUGHT WITH SCRIPTURE</span><h2 id="modal-title">${old?'Edit your note':'A note on this verse'}</h2><p class="modal-intro">${esc(ref)} · ${esc(DATA.translation)}. This note is private to this browser.</p><form data-form="note-save"><input type="hidden" name="ref" value="${esc(ref)}"><div class="field"><label for="note-text">YOUR NOTE</label><textarea id="note-text" name="text" required placeholder="A question, connection, or thought…">${esc(old?.text||'')}</textarea></div><label class="tiny"><input name="private" type="checkbox" ${old?.private!==false?'checked':''}> Keep this note marked private</label><div class="modal-actions">${old?`<button type="button" class="btn danger" data-action="delete-note" data-ref="${esc(ref)}">Delete</button>`:''}<button type="button" class="btn secondary" data-action="modal-close">Cancel</button><button class="btn" type="submit">Save note</button></div></form>`);
  }
  function openJournalModal({ref='',type='reflection',entryId='',title=''}={}) {
    const entry=state.journal.find(e=>e.id===entryId); const initial=entry||{}; const isSoap=type==='soap'||initial.type==='soap'; const formType=isSoap?'soap':'journal';
    const fields=isSoap?`<div class="field full"><label>S · SCRIPTURE</label><input name="scripture" value="${esc(initial.scripture||ref)}" placeholder="Book 1:1"></div><div class="field full"><label>O · OBSERVATION</label><textarea name="observation" placeholder="What do you notice in the passage?">${esc(initial.observation||'')}</textarea></div><div class="field full"><label>A · APPLICATION</label><textarea name="application" placeholder="How could this shape your life?">${esc(initial.application||'')}</textarea></div><div class="field full"><label>P · PRAYER</label><textarea name="prayer" placeholder="Write a prayer…">${esc(initial.prayer||'')}</textarea></div>`:`<div class="field full"><label>REFLECTION</label><textarea name="content" required placeholder="Write what is on your heart…">${esc(initial.content||'')}</textarea></div><div class="field full"><label>OPTIONAL PRAYER</label><textarea name="prayer" placeholder="A prayer to keep with this entry…">${esc(initial.prayer||'')}</textarea></div>`;
    openModal(`<span class="eyebrow">${isSoap?'SCRIPTURE STUDY · SOAP':'PERSONAL JOURNAL'}</span><h2 id="modal-title">${entry?'Edit entry':esc(title||'A moment to reflect')}</h2><p class="modal-intro">Your words stay on this device. Add a reference to keep the reflection with your reading.</p><form data-form="${formType}"><input name="id" type="hidden" value="${esc(entryId)}"><input name="type" type="hidden" value="${esc(isSoap?'soap':type)}"><div class="form-grid"><div class="field full"><label>TITLE</label><input name="title" required value="${esc(initial.title||title||'')}" placeholder="Give this entry a name"></div><div class="field"><label>DATE</label><input name="date" type="date" value="${esc(initial.date||dateKey())}"></div><div class="field"><label>BIBLE REFERENCE</label><input name="reference" value="${esc(initial.reference||ref)}" placeholder="John 3:16"></div>${!isSoap?`<div class="field"><label>MOOD (OPTIONAL)</label><select name="mood"><option value="">Choose a mood</option>${['Peaceful','Hopeful','Searching','Grateful','Heavy','Inspired'].map(x=>`<option ${initial.mood===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>TAGS</label><input name="tags" value="${esc((initial.tags||[]).join(', '))}" placeholder="faith, trust"></div><div class="field full"><label>ENTRY TYPE</label><select name="category"><option ${(initial.category||type)==='reflection'?'selected':''} value="reflection">Reflection</option><option ${(initial.category||type)==='god-moment'?'selected':''} value="god-moment">God moment</option><option ${(initial.category||type)==='gratitude'?'selected':''} value="gratitude">Gratitude</option><option ${(initial.category||type)==='monthly'?'selected':''} value="monthly">Monthly reflection</option></select></div>`:''}${fields}<div class="field full"><label><input type="checkbox" name="private" ${initial.private!==false?'checked':''}> Mark this entry private</label></div></div><div class="modal-actions">${entry?`<button type="button" class="btn danger" data-action="delete-entry" data-id="${esc(entry.id)}">Delete</button>`:''}<button type="button" class="btn secondary" data-action="modal-close">Cancel</button><button type="submit" class="btn">Save to journal</button></div></form>`);
  }
  function renderJournal() {
    const query=(searchQuery||'').toLowerCase(); let entries=[...state.journal].sort((a,b)=>b.date.localeCompare(a.date));
    if(query) entries=entries.filter(e=>JSON.stringify(e).toLowerCase().includes(query));
    const category=$('#journal-filter')?.value; if(category&&category!=='all') entries=entries.filter(e=>(e.category||e.type)===category);
    const html=entries.length?`<div class="journal-grid">${entries.map(e=>`<article class="card journal-card"><div class="journal-card-head"><span class="eyebrow">${esc(dateLabel(e.date).toUpperCase())} ${e.private===false?'':' · 🔒 PRIVATE'}</span><button class="icon-button" data-action="edit-entry" data-id="${esc(e.id)}" title="Edit entry">✎</button></div><h3>${esc(e.title||'Untitled reflection')}</h3><div class="tiny">${esc(e.reference||e.scripture||'Personal reflection')} · ${esc((e.category||e.type||'reflection').replace('-',' '))}</div><p>${esc(e.content||e.observation||e.application||e.prayer||'SOAP study saved.')}</p>${e.prayer?`<div class="tiny"><strong>Prayer:</strong> ${esc(e.prayer)}</div>`:''}<div style="margin-top:10px">${(e.tags||[]).map(t=>`<span class="tag">#${esc(t)}</span>`).join('')}</div></article>`).join('')}</div>`:`<div class="empty-state"><strong>No entries found</strong>${query?'Try another search.':'When you reflect on a passage, your entries will gather here.'}<br><button class="btn small" style="margin-top:12px" data-action="new-journal">Write your first entry</button></div>`;
    $('#page-journal').innerHTML=`<span class="eyebrow">YOUR PERSONAL NOTEBOOK</span><h1>Journal</h1><p class="page-subtitle">A place for the thoughts, questions, prayers, and moments you want to remember.</p><div class="toolbar-row"><input class="text-input" id="journal-search" placeholder="Search your entries…" value="${esc(searchQuery)}" aria-label="Search journal"><select class="control-select" id="journal-filter"><option value="all">All entry types</option><option value="reflection">Reflections</option><option value="soap">SOAP studies</option><option value="god-moment">God moments</option><option value="gratitude">Gratitude</option><option value="monthly">Monthly reflections</option></select><span class="spacer"></span><button class="btn secondary" data-action="new-soap">＋ SOAP study</button><button class="btn" data-action="new-journal">＋ New entry</button></div><div class="tool-grid" style="margin-bottom:18px"><article class="panel"><span class="eyebrow">TODAY I'M THANKFUL FOR…</span><p class="tiny" style="margin:8px 0">Keep up to three small gratitude notes each day.</p><button class="btn small secondary" data-action="gratitude">Add gratitude</button></article><article class="panel"><span class="eyebrow">MONTHLY REFLECTION</span><p class="tiny" style="margin:8px 0">Look back on what you learned, carried, and gave thanks for.</p><button class="btn small secondary" data-action="monthly">Reflect on this month</button></article></div>${html}`;
  }
  function renderPrayer() {
    const cards=state.prayers.length?`<div class="prayer-list">${[...state.prayers].sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt)).map(p=>`<article class="card prayer-card"><div class="journal-card-head"><span class="eyebrow">${esc(p.category||'PERSONAL')} · ${esc(dateLabel(p.date,{month:'short',day:'numeric'}).toUpperCase())}</span><span class="status-pill ${p.status==='Answered'?'answered':''}">${esc(p.status||'Praying')}</span></div><h3>${esc(p.title)}</h3><p>${esc(p.request)}</p>${p.reference?`<div class="tiny">Scripture: <button class="text-link" data-action="read-ref" data-ref="${esc(p.reference)}">${esc(p.reference)}</button></div>`:''}<div class="timeline">${(p.updates||[]).map(u=>`<div class="timeline-item"><time>${esc(dateLabel(u.date,{month:'short',day:'numeric',year:'numeric'}))}</time>${esc(u.text)}</div>`).join('')}</div><div class="btn-row" style="margin-top:14px"><button class="btn small secondary" data-action="prayer-update" data-id="${esc(p.id)}">＋ Add update</button>${p.status!=='Answered'?`<button class="btn small secondary" data-action="prayer-answered" data-id="${esc(p.id)}">Mark answered</button>`:''}<button class="icon-button" data-action="edit-prayer" data-id="${esc(p.id)}" title="Edit prayer">✎</button></div></article>`).join('')}</div>`:`<div class="empty-state"><strong>Your prayer timeline is ready</strong>Add a request and return to note how it changes over time.</div>`;
    $('#page-prayer').innerHTML=`<span class="eyebrow">A SPACE FOR PRAYER</span><h1>Prayer journal</h1><p class="page-subtitle">Keep requests, updates, and gratitude in one quiet place. Only you decide when a prayer is answered.</p><div class="toolbar-row"><span class="spacer"></span><button class="btn" data-action="new-prayer">＋ Add a prayer</button></div>${cards}`;
  }
  function openPrayerModal(id='') {
    const p=state.prayers.find(x=>x.id===id)||{};
    openModal(`<span class="eyebrow">PRAYER JOURNAL</span><h2 id="modal-title">${id?'Edit prayer request':'What is on your heart?'}</h2><p class="modal-intro">You can update this request over time. It will only be marked answered when you choose.</p><form data-form="prayer"><input name="id" type="hidden" value="${esc(id)}"><div class="form-grid"><div class="field full"><label>PRAYER TITLE</label><input name="title" required value="${esc(p.title||'')}" placeholder="Prayer for a friend"></div><div class="field full"><label>REQUEST</label><textarea name="request" required placeholder="Write your prayer request…">${esc(p.request||'')}</textarea></div><div class="field"><label>CATEGORY</label><select name="category">${['Family','Friends','School','Personal','Church','Thanksgiving','Guidance','Others'].map(c=>`<option ${p.category===c?'selected':''}>${c}</option>`).join('')}</select></div><div class="field"><label>STATUS</label><select name="status">${['Praying','Waiting','Answered'].map(c=>`<option ${p.status===c?'selected':''}>${c}</option>`).join('')}</select></div><div class="field"><label>DATE</label><input name="date" type="date" value="${esc(p.date||dateKey())}"></div><div class="field"><label>OPTIONAL VERSE</label><input name="reference" value="${esc(p.reference||'')}" placeholder="Psalm 23:1"></div></div><div class="modal-actions"><button type="button" class="btn secondary" data-action="modal-close">Cancel</button><button class="btn" type="submit">Save prayer</button></div></form>`);
  }
  function openMonthlyModal() {
    const month = new Date().toLocaleDateString(undefined,{month:'long',year:'numeric'});
    openModal(`<span class="eyebrow">MONTHLY REFLECTION</span><h2 id="modal-title">My month with God</h2><p class="modal-intro">Take a little time to remember ${esc(month)}. Your answers will be saved as a journal entry.</p><form data-form="monthly"><div class="field"><label>WHAT DID I LEARN?</label><textarea name="learned" placeholder="A truth, lesson, or new understanding…"></textarea></div><div class="field"><label>WHAT CHALLENGED ME?</label><textarea name="challenged" placeholder="A hard moment or question…"></textarea></div><div class="field"><label>WHAT AM I THANKFUL FOR?</label><textarea name="thankful" placeholder="People, moments, or gifts…"></textarea></div><div class="field"><label>WHAT PRAYERS WERE ANSWERED?</label><textarea name="answered" placeholder="Only what you recognize as answered…"></textarea></div><div class="field"><label>WHAT SCRIPTURE STAYED WITH ME?</label><input name="scripture" placeholder="Book 1:1"></div><div class="field"><label>WHAT DO I WANT TO GROW IN NEXT MONTH?</label><textarea name="next" placeholder="A hope or intention…"></textarea></div><div class="modal-actions"><button class="btn secondary" type="button" data-action="modal-close">Cancel</button><button class="btn" type="submit">Save reflection</button></div></form>`);
  }
  function openGratitudeModal() {
    const count=state.journal.filter(e=>e.date===dateKey()&&e.category==='gratitude').length;
    if(count>=3){toast('You have saved three gratitude entries for today.');return;}
    openModal(`<span class="eyebrow">GRATITUDE · ${3-count} ${3-count===1?'ENTRY':'ENTRIES'} LEFT TODAY</span><h2 id="modal-title">Today I’m thankful for…</h2><p class="modal-intro">Save one to three small things you want to remember.</p><form data-form="gratitude"><div class="field"><label>ONE THING</label><input name="item1" required placeholder="A moment, person, or gift"></div><div class="field"><label>ANOTHER (OPTIONAL)</label><input name="item2" placeholder="Something else you noticed"></div><div class="field"><label>ONE MORE (OPTIONAL)</label><input name="item3" placeholder="A small thing that mattered"></div><div class="modal-actions"><button class="btn secondary" type="button" data-action="modal-close">Cancel</button><button class="btn" type="submit">Save gratitude</button></div></form>`);
  }
  function openPrayerUpdate(id) {
    openModal(`<span class="eyebrow">PRAYER TIMELINE</span><h2 id="modal-title">Add an update</h2><p class="modal-intro">Record where you are with this request today.</p><form data-form="prayer-update"><input type="hidden" name="id" value="${esc(id)}"><div class="field"><label>UPDATE</label><textarea name="text" required placeholder="A new thought, a change, or simply that you are still praying…"></textarea></div><div class="modal-actions"><button class="btn secondary" type="button" data-action="modal-close">Cancel</button><button class="btn" type="submit">Add to timeline</button></div></form>`);
  }
  function renderPlans() {
    const current=plans.find(p=>p.id===state.reading.plan);
    const cards=plans.map(p=>{const active=state.reading.plan===p.id; const n=active?state.reading.completed.length:0; const pct=active?Math.round(n/p.days*100):0;return `<article class="card plan-card"><span class="eyebrow">${p.days} DAYS · PERSONAL PACE</span><h3>${esc(p.title)}</h3><p>${esc(p.subtitle)}</p><div class="plan-bottom">${active?`<div class="progress-track"><span style="width:${pct}%"></span></div><span class="progress-percent">${n}/${p.days}</span><button class="btn small secondary" data-action="plan-toggle">${state.reading.paused?'Resume':'Pause'}</button>`:`<span class="tiny">${esc(p.references.slice(0,2).join(' · '))}</span><button class="btn small" data-action="start-plan" data-id="${p.id}">${state.reading.history.includes(p.id)?'Start again':'Start plan'}</button>`}</div></article>`;}).join('');
    $('#page-plans').innerHTML=`<span class="eyebrow">READING AT YOUR OWN PACE</span><h1>Reading plans</h1><p class="page-subtitle">Choose a path to help you make room for the Word. Progress is personal; there are no scores or streak pressure.</p>${current?`<div class="panel" style="margin-bottom:17px"><div class="journal-card-head"><div><span class="eyebrow">CURRENT PLAN ${state.reading.paused?'· PAUSED':''}</span><h2 style="margin:7px 0 4px">${esc(current.title)}</h2><p class="tiny">Day ${Math.min(state.reading.day,current.days)} of ${current.days} · ${current.references[Math.min(state.reading.day-1,current.references.length-1)]}</p></div><div class="btn-row"><button class="btn secondary" data-action="plan-open">Read today's passage</button><button class="btn" data-action="plan-complete">Mark complete</button></div></div><div class="progress-track" style="height:7px"><span style="width:${Math.round(state.reading.completed.length/current.days*100)}%"></span></div></div>`:''}<div class="plan-grid">${cards}</div><div class="panel" style="margin-top:18px"><span class="eyebrow">PLAN HISTORY</span><p class="tiny" style="margin:8px 0 0">${state.reading.history.length?state.reading.history.map(id=>esc(plans.find(p=>p.id===id)?.title||id)).join(' · '):'Plans you complete or replace will appear here.'}</p></div>`;
  }
  function renderMyBible() {
    const booksmarks=state.bookmarks; const favs=state.favorites; const highlights=Object.entries(state.highlights);
    const savedRows=(refs,kind)=>refs.length?`<div class="saved-list">${refs.map(ref=>{const parsed=parseReference(ref);const txt=parsed?verseText(parsed.book,parsed.chapter,parsed.verse):'';return `<div class="panel saved-row"><div class="saved-ref">${esc(ref)}</div><div class="saved-text">${esc(txt)}</div><div class="saved-actions"><button class="icon-button" data-action="read-ref" data-ref="${esc(ref)}" title="Read">↗</button><button class="icon-button" data-action="journal-ref" data-ref="${esc(ref)}" title="Journal">✎</button><button class="icon-button" data-action="remove-saved" data-kind="${kind}" data-ref="${esc(ref)}" title="Remove">×</button></div></div>`;}).join('')}</div>`:`<div class="empty-state">Nothing saved here yet. Choose a verse while reading to keep it close.</div>`;
    const highlightRows=highlights.length?`<div class="saved-list">${highlights.map(([ref,color])=>{const p=parseReference(ref);return `<div class="panel saved-row"><span class="highlight-dot" style="background:${esc(color)}"></span><div class="saved-ref">${esc(ref)}</div><div class="saved-text">${esc(p?verseText(p.book,p.chapter,p.verse):'')}</div><div class="saved-actions"><button class="icon-button" data-action="read-ref" data-ref="${esc(ref)}" title="Read">↗</button><button class="icon-button" data-action="unhighlight" data-ref="${esc(ref)}" title="Remove highlight">×</button></div></div>`;}).join('')}</div>`:`<div class="empty-state">No highlights yet. Highlight a verse from the reader.</div>`;
    const memory=state.memory.length?state.memory:[]; const mem=memory[0]; let memVerse=mem?parseReference(mem.ref):parseReference('Philippians 4:13'); const memText=memVerse?verseText(memVerse.book,memVerse.chapter,memVerse.verse):'I can do all things through Christ which strengtheneth me.';
    let masked=memText; if(mem&&mem.level>0) {const words=memText.split(' ');const count=Math.ceil(words.length*({1:.2,2:.4,3:.65}[mem.level]||.2));let hidden=0;masked=words.map(w=>{if(hidden<count&&/[A-Za-z]/.test(w)){hidden++;return `<span class="memory-hidden">${esc(w)}</span>`}return esc(w)}).join(' ');}
    $('#page-mybible').innerHTML=`<span class="eyebrow">WHAT YOU'VE KEPT</span><h1>My Bible</h1><p class="page-subtitle">Verses, notes, and small goals gathered as you read.</p><div class="section-heading"><h2>My favorites</h2></div>${savedRows(favs,'favorites')}<div class="section-heading"><h2>My highlights</h2></div>${highlightRows}<div class="section-heading"><h2>Bookmarks</h2></div>${savedRows(bookmarks,'bookmarks')}<div class="section-heading"><h2>Scripture memory</h2><button class="btn small secondary" data-action="memory-add">＋ Add a verse</button></div><div class="panel memory-card"><span class="eyebrow">${esc(mem?.ref||'PHILIPPIANS 4:13')} · ${mem?`LEVEL ${mem.level||0} · ${mem.progress||0} PRACTICE SESSIONS`:'START WITH A SAMPLE VERSE'}</span><div class="memory-verse">${masked}</div><div class="btn-row"><button class="btn small secondary" data-action="memory-level">Hide more words</button><button class="btn small" data-action="memory-practiced">I practiced this</button>${mem?`<button class="btn small secondary" data-action="memory-remove" data-id="${esc(mem.id)}">Remove</button>`:''}</div></div><div class="section-heading"><h2>Personal goals</h2><button class="btn small secondary" data-action="goal-add">＋ Add a goal</button></div><div class="panel">${state.goals.length?state.goals.map(g=>`<label class="goal-item"><input type="checkbox" data-action="goal-toggle" data-id="${esc(g.id)}" ${g.done?'checked':''}><span>${esc(g.text)}</span><span class="spacer"></span><button class="icon-button" type="button" data-action="goal-delete" data-id="${esc(g.id)}" title="Remove goal">×</button></label>`).join(''):'<div class="empty-state">Set a personal intention for your reading, prayer, or memorization.</div>'}</div><div class="section-heading"><h2>My notes</h2></div>${Object.keys(state.notes).length?`<div class="saved-list">${Object.entries(state.notes).map(([ref,n])=>`<div class="panel saved-row"><div class="saved-ref">${esc(ref)}</div><div class="saved-text">${esc(n.text)}</div><div class="saved-actions"><button class="icon-button" data-action="read-ref" data-ref="${esc(ref)}">↗</button><button class="icon-button" data-action="note" data-ref="${esc(ref)}">✎</button></div></div>`).join('')}</div>`:'<div class="empty-state">Add a note from the reader to keep it here.</div>'}`;
  }
  function openGoalModal() { openModal(`<span class="eyebrow">A PERSONAL INTENTION</span><h2 id="modal-title">Set a gentle goal</h2><p class="modal-intro">Choose something meaningful to you. Your goals are private and non-competitive.</p><form data-form="goal"><div class="field"><label>MY GOAL</label><input name="text" required placeholder="Read one chapter today"></div><div class="modal-actions"><button type="button" class="btn secondary" data-action="modal-close">Cancel</button><button type="submit" class="btn">Add goal</button></div></form>`); }
  function renderStudy() {
    const board=state.studyBoards.find(b=>b.id===state.currentBoardId)||state.studyBoards[0]; if(board&&!state.currentBoardId)state.currentBoardId=board.id;
    const boardSelect=state.studyBoards.length?`<select id="board-select" class="control-select">${state.studyBoards.map(b=>`<option value="${esc(b.id)}" ${board?.id===b.id?'selected':''}>${esc(b.title)}</option>`).join('')}</select>`:'';
    const nodes=(board?.nodes||[]).map(n=>`<div class="board-node ${esc(n.kind||'')}" data-node="${esc(n.id)}" style="left:${n.x||30}px;top:${n.y||25}px">${esc(n.text)}<button data-action="board-delete-node" data-id="${esc(n.id)}" aria-label="Delete note">×</button></div>`).join('');
    $('#page-study').innerHTML=`<span class="eyebrow">A VISUAL STUDY NOTEBOOK</span><h1>Study space</h1><p class="page-subtitle">Arrange thoughts, prayers, and passage references on a personal study board. Drag cards to move them.</p><div class="toolbar-row">${boardSelect}<span class="spacer"></span><button class="btn secondary" data-action="board-new">＋ New canvas</button>${board?`<button class="btn secondary" data-action="board-add" data-kind="note">＋ Note</button><button class="btn secondary" data-action="board-add" data-kind="prayer">＋ Prayer</button><button class="btn secondary" data-action="board-add" data-kind="reference">＋ Scripture</button><button class="btn danger small" data-action="board-delete" data-id="${esc(board.id)}">Delete canvas</button>`:''}</div>${board?`<div class="panel" style="margin-bottom:11px"><span class="eyebrow">${esc(board.reference||'PERSONAL STUDY')}</span><strong style="margin-left:9px">${esc(board.title)}</strong></div><div class="study-board" id="study-board">${nodes||'<div class="empty-state" style="margin:24px;background:rgba(255,253,248,.85)"><strong>Your canvas is ready</strong>Add a note, prayer, or scripture card above.</div>'}</div><p class="scope-note" style="margin-top:10px">Cards are saved as you move them. Double-click a card to edit its words.</p>`:`<div class="empty-state"><strong>Create a study canvas</strong>Start from a passage or make a blank board for your study.</div>`}`;
  }
  function openBoardModal(ref='') { openModal(`<span class="eyebrow">STUDY CANVAS</span><h2 id="modal-title">Start a study board</h2><p class="modal-intro">A personal space for a passage, questions, and prayer.</p><form data-form="board-create"><div class="field"><label>BOARD TITLE</label><input name="title" required placeholder="Romans 8 — hope and assurance" value="${esc(ref?`Study of ${ref}`:'')}"></div><div class="field"><label>PASSAGE</label><input name="reference" value="${esc(ref)}" placeholder="Romans 8"></div><div class="modal-actions"><button type="button" class="btn secondary" data-action="modal-close">Cancel</button><button class="btn" type="submit">Create canvas</button></div></form>`); }
  function renderSettings() {
    $('#page-settings').innerHTML=`<span class="eyebrow">YOUR PREFERENCES</span><h1>Settings</h1><p class="page-subtitle">Make this reading space feel comfortable. Your data lives in this browser only.</p><div class="settings-grid"><article class="panel"><h3>Reading preferences</h3><div class="setting-row"><div><label for="name-setting">Your name</label><small>Used for a simple greeting on Home.</small></div><input class="text-input" id="name-setting" type="text" maxlength="40" value="${esc(state.name)}" placeholder="Name"></div><div class="setting-row"><div><label for="theme-setting">Appearance</label><small>Choose a light or dark reading space.</small></div><select class="control-select" id="theme-setting"><option value="light" ${state.preferences.theme==='light'?'selected':''}>Warm paper</option><option value="dark" ${state.preferences.theme==='dark'?'selected':''}>Evening</option></select></div><div class="setting-row"><div><label for="font-setting">Reader font size</label><small>${Number(state.preferences.fontSize)} px</small></div><input id="font-setting" type="range" min="16" max="25" value="${Number(state.preferences.fontSize)}"></div><div class="setting-row"><div><label for="spacing-setting">Line spacing</label><small>Change the breathing room between verses.</small></div><input id="spacing-setting" type="range" min="1.5" max="2.3" step="0.05" value="${Number(state.preferences.lineHeight)}"></div><div class="setting-row"><div><label>Translation</label><small>KJV sample content in this edition.</small></div><span class="status-pill">King James Version</span></div></article><article class="panel"><h3>Daily reminder</h3><div class="setting-row"><div><label for="reminder-setting">Preferred time</label><small>Save the time you would like a reminder.</small></div><input class="control-input" id="reminder-setting" type="time" value="${esc(state.preferences.reminder)}"></div><p class="scope-note">This static site stores your preferred time. It does not send notifications while the browser is closed.</p><h3 style="margin-top:26px">Privacy &amp; backup</h3><div class="privacy-card panel"><strong>Your journal data is stored locally on this device.</strong><p class="tiny" style="margin:7px 0 0">No account is required and journal content is not sent to a server. Clearing browser data will remove it, so keep an export as a backup.</p></div><div class="btn-row" style="margin-top:13px"><button class="btn" data-action="export">Export my data</button><button class="btn secondary" data-action="import">Import backup</button></div></article></div><article class="panel" style="margin-top:15px"><h3>About this edition</h3><p class="tiny" style="line-height:1.7">The bundled King James Version sample contains selected chapters from ten books. The translation and app are separated in the project data layer; additional translations should only be added with appropriate permissions. Your notes, prayers, highlights, bookmarks, reading progress, and study boards are stored in your browser's local storage.</p><button class="btn small danger" data-action="reset-data">Clear all local data</button></article>`;
  }
  function openModal(html) { $('#modal-content').innerHTML=html; $('#modal-backdrop').hidden=false; const focus=$('#modal-content input:not([type=hidden]),#modal-content textarea,#modal-content button'); setTimeout(()=>focus?.focus(),20); }
  function closeModal() { $('#modal-backdrop').hidden=true; $('#modal-content').innerHTML=''; }
  function openMore() { openModal(`<span class="eyebrow">YOUR SPACE</span><h2 id="modal-title">More places</h2><p class="modal-intro">Choose a place to continue.</p><div class="tool-grid">${[['plans','Reading plans'],['mybible','My Bible'],['study','Study space'],['settings','Settings']].map(([p,t])=>`<button class="btn secondary" data-action="go-page" data-page="${p}">${t}</button>`).join('')}</div>`); }
  function openSearch() { openModal(`<span class="eyebrow">SEARCH THE INCLUDED TEXT</span><h2 id="modal-title">Find a passage</h2><p class="modal-intro">Search by reference (John 3:16) or a word in the included KJV chapters.</p><input class="text-input search-modal-input" id="scripture-search" placeholder="Try “John 3:16” or “peace”" value="${esc(searchQuery)}" autocomplete="off"><div class="search-results" id="search-results"></div>`); $('#scripture-search').addEventListener('input',e=>renderSearchResults(e.target.value)); if(searchQuery)renderSearchResults(searchQuery); }
  function renderSearchResults(q) {
    const box=$('#search-results'); if(!box)return; const query=q.trim(); if(!query){box.innerHTML='<div class="empty-state">Type a reference or keyword to search.</div>';return;}
    const parsed=parseReference(query);
    let hits=[];
    if(parsed) {const text=verseText(parsed.book,parsed.chapter,parsed.verse);hits=[{ref:refFor(parsed.book,parsed.chapter,parsed.verse),text}];}
    else hits=knownRefs().filter(x=>verseText(x.book,x.chapter,x.verse).toLowerCase().includes(query.toLowerCase())).slice(0,40).map(x=>({ref:refFor(x.book,x.chapter,x.verse),text:verseText(x.book,x.chapter,x.verse)}));
    box.innerHTML=hits.length?hits.map(h=>`<button class="search-result" data-action="read-ref" data-ref="${esc(h.ref)}"><strong>${esc(h.ref)}</strong><span>${esc(h.text)}</span></button>`).join(''):'<div class="empty-state">No match in this edition’s included chapters.</div>';
  }
  function downloadFile(filename, text, mime='application/json') { const blob=new Blob([text],{type:mime}); const link=document.createElement('a'); link.href=URL.createObjectURL(blob); link.download=filename; document.body.append(link); link.click(); link.remove(); setTimeout(()=>URL.revokeObjectURL(link.href),1000); }
  function exportData() { const payload={format:'e-journal-bible-backup',version:1,exportedAt:new Date().toISOString(),data:state}; downloadFile(`e-journal-bible-backup-${dateKey()}.json`,JSON.stringify(payload,null,2)); toast('Backup exported. Keep it somewhere safe.'); }
  function importData(file) {
    const reader=new FileReader(); reader.onload=()=>{try{const raw=JSON.parse(reader.result);const candidate=raw.data||raw;if(!candidate||typeof candidate!=='object'||!Array.isArray(candidate.journal)||!Array.isArray(candidate.prayers))throw new Error('Invalid backup'); state={...clone(DEFAULTS),...candidate,reader:{...DEFAULTS.reader,...candidate.reader},preferences:{...DEFAULTS.preferences,...candidate.preferences},reading:{...DEFAULTS.reading,...candidate.reading}};persist();closeModal();setPage('home');toast('Your backup was imported.');}catch{toast('That file does not look like an E-Journal Bible backup.');}}; reader.readAsText(file); }
  function bindCanvas(key) {
    const canvas=$('#annotation-canvas'), box=$('#verse-list'); if(!canvas||!box)return;
    box.append(canvas);
    const fit=()=>{const rect=box.getBoundingClientRect(),dpr=window.devicePixelRatio||1;canvas.width=Math.round(rect.width*dpr);canvas.height=Math.round(rect.height*dpr);canvas.style.width=`${rect.width}px`;canvas.style.height=`${rect.height}px`;const ctx=canvas.getContext('2d');ctx.setTransform(dpr,0,0,dpr,0,0);replayStrokes(ctx,key,rect.width,rect.height);};
    const resize=()=>fit(); requestAnimationFrame(fit); window.addEventListener('resize',resize,{once:true});
    if(!annotating)return;
    let active=null;
    canvas.addEventListener('pointerdown',e=>{e.preventDefault();canvas.setPointerCapture(e.pointerId);const r=canvas.getBoundingClientRect();active={id:uid(),tool:annotationTool,color:annotationColor,width:annotationWidth,points:[{x:(e.clientX-r.left)/r.width,y:(e.clientY-r.top)/r.height,p:e.pressure||.5}]};redoStrokes=[];drawLive();});
    canvas.addEventListener('pointermove',e=>{if(!active)return;const r=canvas.getBoundingClientRect();active.points.push({x:(e.clientX-r.left)/r.width,y:(e.clientY-r.top)/r.height,p:e.pressure||.5});drawLive();});
    const finish=e=>{if(!active)return;if(active.points.length===1)active.points.push({...active.points[0],x:Math.min(1,active.points[0].x+.001)});const arr=state.annotations[key]||(state.annotations[key]=[]);arr.push(active);active=null;persist();drawLive();};
    canvas.addEventListener('pointerup',finish);canvas.addEventListener('pointercancel',finish);
    function drawLive(){const ctx=canvas.getContext('2d'),r=canvas.getBoundingClientRect(),dpr=window.devicePixelRatio||1;ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,r.width,r.height);replayStrokes(ctx,key,r.width,r.height);if(active)drawStroke(ctx,active,r.width,r.height);}
  }
  function replayStrokes(ctx,key,w,h) { for(const stroke of state.annotations[key]||[])drawStroke(ctx,stroke,w,h); }
  function drawStroke(ctx,stroke,w,h) {
    const pts=stroke.points||[]; if(!pts.length)return;ctx.save();ctx.globalCompositeOperation=stroke.tool==='eraser'?'destination-out':'source-over';ctx.globalAlpha=stroke.tool==='highlighter'?.27:1;ctx.strokeStyle=stroke.color;ctx.fillStyle=stroke.color;ctx.lineWidth=stroke.width*(stroke.tool==='highlighter'?2.2:1);ctx.lineCap='round';ctx.lineJoin='round';ctx.beginPath();ctx.moveTo(pts[0].x*w,pts[0].y*h);for(let i=1;i<pts.length;i++){const p=pts[i];ctx.lineWidth=stroke.width*(stroke.tool==='highlighter'?2.2:1)*(.75+(p.p||.5)*.5);ctx.lineTo(p.x*w,p.y*h);}ctx.stroke();ctx.restore();
  }
  function pushBoardNode(kind) {
    const board=state.studyBoards.find(b=>b.id===state.currentBoardId); if(!board)return;const text=kind==='reference'?currentRef():kind==='prayer'?'Prayer\n': 'A thought to keep…';board.nodes.push({id:uid(),kind,text,x:30+board.nodes.length*24,y:35+board.nodes.length*22});persist();renderStudy();
  }
  function boardById() { return state.studyBoards.find(b=>b.id===state.currentBoardId); }
  let dragNode=null;
  document.addEventListener('click', e => {
    const action=e.target.closest('[data-action]'); if(action){const a=action.dataset.action;const ref=action.dataset.ref||currentRef();
      if(a==='go-page'){closeModal();setPage(action.dataset.page);return;}
      if(a==='modal-close'){closeModal();return;}
      if(a==='continue-reading'){setPage('bible');return;}
      if(a==='read-ref'){closeModal();goToReference(action.dataset.ref);return;}
      if(a==='journal-ref'){const r=action.dataset.ref;closeModal();openJournalModal({ref:r,title:`Reflection on ${r}`});return;}
      if(a==='continue-plan'){setPage('plans');return;}
      if(a==='new-journal'){openJournalModal();return;}
      if(a==='new-soap'){openJournalModal({type:'soap',ref:`${state.reader.book} ${state.reader.chapter}`});return;}
      if(a==='gratitude'){openGratitudeModal();return;}
      if(a==='monthly'){openMonthlyModal();return;}
      if(a==='edit-entry'){openJournalModal({entryId:action.dataset.id});return;}
      if(a==='delete-entry'){state.journal=state.journal.filter(x=>x.id!==action.dataset.id);persist();closeModal();renderJournal();toast('Journal entry deleted.');return;}
      if(a==='new-prayer'){openPrayerModal();return;}
      if(a==='edit-prayer'){openPrayerModal(action.dataset.id);return;}
      if(a==='prayer-update'){openPrayerUpdate(action.dataset.id);return;}
      if(a==='prayer-answered'){const p=state.prayers.find(x=>x.id===action.dataset.id);if(p){p.status='Answered';p.updatedAt=new Date().toISOString();p.updates.push({date:dateKey(),text:'Marked as answered by me.'});persist();renderPrayer();toast('Prayer marked answered.');}return;}
      if(a==='start-plan'){if(state.reading.plan&&state.reading.plan!==action.dataset.id&&!state.reading.history.includes(state.reading.plan))state.reading.history.push(state.reading.plan);state.reading.plan=action.dataset.id;state.reading.day=1;state.reading.completed=[];state.reading.paused=false;persist();renderPlans();toast('Reading plan started at your pace.');return;}
      if(a==='plan-open'){const plan=plans.find(p=>p.id===state.reading.plan);if(plan)goToReference(plan.references[Math.min(state.reading.day-1,plan.references.length-1)]);return;}
      if(a==='plan-toggle'){state.reading.paused=!state.reading.paused;persist();renderPlans();return;}
      if(a==='plan-complete'){const plan=plans.find(p=>p.id===state.reading.plan);if(!plan)return;if(state.reading.paused){toast('Resume this plan before marking progress.');return;}const day=state.reading.day;if(!state.reading.completed.includes(day))state.reading.completed.push(day);state.reading.day=Math.min(plan.days,day+1);if(state.reading.completed.length>=plan.days){if(!state.reading.history.includes(plan.id))state.reading.history.push(plan.id);state.reading.plan=null;toast('You completed this plan. Well done taking the time.');}else toast('Today’s reading marked complete.');persist();renderPlans();return;}
      if(a==='chapter-complete'){const key=`${state.reader.book}|${state.reader.chapter}`;if(!state.reading.chaptersRead.includes(key))state.reading.chaptersRead.push(key);state.reader.lastReadAt=new Date().toISOString();persist();renderBible();toast('Chapter marked as read.');return;}
      if(a==='chapter-reflection'){openJournalModal({ref:`${state.reader.book} ${state.reader.chapter}`,title:`What stood out · ${state.reader.book} ${state.reader.chapter}`});return;}
      if(a==='select-verse'){state.reader.selectedVerse=Number(action.dataset.verse);persist();renderBible();return;}
      if(a==='highlight'){highlight(ref);return;}
      if(a==='highlight-color'){state.highlights[ref]=action.dataset.color;persist();renderBible();toast('Highlight saved.');return;}
      if(a==='unhighlight'){delete state.highlights[action.dataset.ref];persist();renderMyBible();return;}
      if(a==='bookmark'){toggleSaved('bookmarks',ref);return;}
      if(a==='favorite'){toggleSaved('favorites',ref);return;}
      if(a==='favorite-ref'){toggleSaved('favorites',action.dataset.ref);return;}
      if(a==='remove-saved'){state[action.dataset.kind]=state[action.dataset.kind].filter(x=>x!==action.dataset.ref);persist();renderMyBible();return;}
      if(a==='note'){openNoteModal(action.dataset.ref||ref);return;}
      if(a==='delete-note'){delete state.notes[action.dataset.ref];persist();closeModal();renderBible();toast('Note deleted.');return;}
      if(a==='save-quick-note'){const t=$('#quick-note')?.value.trim();if(t){state.notes[action.dataset.ref]={text:t,private:true,updatedAt:new Date().toISOString()};persist();renderBible();toast('Verse note saved.');}return;}
      if(a==='save-chapter-note'){const t=$('#chapter-note')?.value.trim();if(t){state.notes[action.dataset.ref]={text:t,private:true,updatedAt:new Date().toISOString()};persist();renderBible();toast('Chapter note saved.');}return;}
      if(a==='copy'){copyVerse(ref);return;}
      if(a==='share'){shareVerse(ref);return;}
      if(a==='side-tab'){sideTab=action.dataset.tab;renderBible();return;}
      if(a==='toggle-annotate'){annotating=!annotating;redoStrokes=[];renderBible();if(annotating)toast('Draw directly on the Bible page.');return;}
      if(a==='annotation-tool'){annotationTool=action.dataset.tool;renderBible();return;}
      if(a==='undo-annotation'){const list=state.annotations[passageKey()]||[];if(list.length){redoStrokes.push(list.pop());persist();renderBible();}return;}
      if(a==='redo-annotation'){const item=redoStrokes.pop();if(item){(state.annotations[passageKey()]||(state.annotations[passageKey()]=[])).push(item);persist();renderBible();}return;}
      if(a==='clear-annotation'){if(confirm('Clear all handwritten marks on this chapter?')){delete state.annotations[passageKey()];redoStrokes=[];persist();renderBible();}return;}
      if(a==='search-open'){openSearch();return;}
      if(a==='memory-add'){openModal(`<span class="eyebrow">SCRIPTURE MEMORY</span><h2 id="modal-title">Keep a verse close</h2><form data-form="memory-add"><div class="field"><label>REFERENCE FROM INCLUDED CHAPTERS</label><input name="ref" required value="${esc(currentRef())}" placeholder="Philippians 4:13"></div><div class="modal-actions"><button class="btn secondary" type="button" data-action="modal-close">Cancel</button><button class="btn" type="submit">Add verse</button></div></form>`);return;}
      if(a==='memory-level'){const m=state.memory[0]||(state.memory[0]={id:uid(),ref:'Philippians 4:13',level:0,progress:0});m.level=((m.level||0)+1)%4;persist();renderMyBible();return;}
      if(a==='memory-practiced'){const m=state.memory[0]||(state.memory[0]={id:uid(),ref:'Philippians 4:13',level:0,progress:0});m.progress=(m.progress||0)+1;persist();renderMyBible();toast('Practice noted. Keep going at your own pace.');return;}
      if(a==='memory-remove'){state.memory=state.memory.filter(x=>x.id!==action.dataset.id);persist();renderMyBible();return;}
      if(a==='goal-add'){openGoalModal();return;}
      if(a==='goal-delete'){state.goals=state.goals.filter(g=>g.id!==action.dataset.id);persist();renderMyBible();return;}
      if(a==='board-new'){openBoardModal();return;}
      if(a==='study-add-ref'){setPage('study');if(!state.studyBoards.length){openBoardModal(currentRef());}else{pushBoardNode('reference');}return;}
      if(a==='board-add'){pushBoardNode(action.dataset.kind);return;}
      if(a==='board-delete-node'){const b=boardById();if(b)b.nodes=b.nodes.filter(n=>n.id!==action.dataset.id);persist();renderStudy();return;}
      if(a==='board-delete'){if(confirm('Delete this study canvas and its cards?')){state.studyBoards=state.studyBoards.filter(b=>b.id!==action.dataset.id);state.currentBoardId=state.studyBoards[0]?.id||null;persist();renderStudy();}return;}
      if(a==='export'){exportData();return;}
      if(a==='import'){$('#import-file').click();return;}
      if(a==='reset-data'){if(confirm('Clear all journal content and preferences stored on this device? Export a backup first if you want to keep it.')){localStorage.removeItem(KEY);state=clone(DEFAULTS);persist();setPage('home');toast('Local data cleared.');}return;}
      if(a==='modal-close'){closeModal();return;}
    }
    const nav=e.target.closest('[data-page]'); if(nav){setPage(nav.dataset.page);return;}
  });
  document.addEventListener('submit',e=>{
    const form=e.target.closest('form[data-form]');if(!form)return;e.preventDefault();const data=Object.fromEntries(new FormData(form).entries());const type=form.dataset.form;
    if(type==='note-save'){state.notes[data.ref]={text:data.text.trim(),private:form.elements.private.checked,updatedAt:new Date().toISOString()};persist();closeModal();renderBible();toast('Verse note saved.');}
    if(type==='monthly'){const answers=[['What I learned',data.learned],['What challenged me',data.challenged],['What I am thankful for',data.thankful],['Answered prayers',data.answered],['Scripture that stayed with me',data.scripture],['What I hope to grow in',data.next]].filter(([,v])=>v?.trim());const content=answers.map(([q,v])=>`${q}: ${v.trim()}`).join('\n\n');if(!content){toast('Add at least one reflection before saving.');return;}state.journal.unshift({id:uid(),type:'monthly',category:'monthly',title:`My month with God · ${new Date().toLocaleDateString(undefined,{month:'long',year:'numeric'})}`,date:dateKey(),reference:data.scripture||'',content,monthlyAnswers:data,private:true,updatedAt:new Date().toISOString()});persist();closeModal();renderJournal();toast('Monthly reflection saved.');}
    if(type==='gratitude'){const count=state.journal.filter(e=>e.date===dateKey()&&e.category==='gratitude').length;if(count>=3){toast('You have saved three gratitude entries for today.');return;}const items=[data.item1,data.item2,data.item3].map(x=>x?.trim()).filter(Boolean);if(!items.length){toast('Add something you are thankful for.');return;}state.journal.unshift({id:uid(),type:'gratitude',category:'gratitude',title:'Today I’m thankful for…',date:dateKey(),reference:'',content:items.map((x,i)=>`${i+1}. ${x}`).join('\n'),tags:['gratitude'],private:true,updatedAt:new Date().toISOString()});persist();closeModal();renderJournal();toast('Gratitude saved in your journal.');}
    if(type==='journal'||type==='soap'){const old=state.journal.find(x=>x.id===data.id);const entry={...(old||{}),id:data.id||uid(),type:data.type||type,title:data.title.trim(),date:data.date||dateKey(),reference:data.reference||data.scripture||'',scripture:data.scripture||'',content:data.content||'',observation:data.observation||'',application:data.application||'',prayer:data.prayer||'',mood:data.mood||'',tags:(data.tags||'').split(',').map(x=>x.trim()).filter(Boolean),category:data.category||data.type||'reflection',private:form.elements.private.checked,updatedAt:new Date().toISOString()};if(!old)entry.createdAt=entry.updatedAt;old?Object.assign(old,entry):state.journal.unshift(entry);persist();closeModal();if(state.page==='journal')renderJournal();else renderHome();toast('Reflection saved in your journal.');}
    if(type==='prayer'){const old=state.prayers.find(x=>x.id===data.id);const prayer={...(old||{}),id:data.id||uid(),title:data.title.trim(),request:data.request.trim(),category:data.category,status:data.status,date:data.date||dateKey(),reference:data.reference.trim(),updatedAt:new Date().toISOString(),updates:old?.updates||[{date:data.date||dateKey(),text:'Prayer request added.'}]};if(old&&old.status!==data.status)prayer.updates.push({date:dateKey(),text:`Status changed to ${data.status}.`});old?Object.assign(old,prayer):state.prayers.unshift(prayer);persist();closeModal();renderPrayer();toast('Prayer request saved.');}
    if(type==='prayer-update'){const p=state.prayers.find(x=>x.id===data.id);if(p){p.updates.push({date:dateKey(),text:data.text.trim()});p.updatedAt=new Date().toISOString();persist();closeModal();renderPrayer();toast('Timeline updated.');}}
    if(type==='goal'){state.goals.push({id:uid(),text:data.text.trim(),done:false});persist();closeModal();renderMyBible();toast('Personal goal added.');}
    if(type==='memory-add'){const parsed=parseReference(data.ref);if(!parsed){toast('Use a verse included in this KJV sample.');return;}if(!state.memory.some(x=>x.ref===data.ref)){state.memory.unshift({id:uid(),ref:data.ref,level:0,progress:0});}persist();closeModal();renderMyBible();toast('Verse added to Scripture memory.');}
    if(type==='board-create'){const b={id:uid(),title:data.title.trim(),reference:data.reference.trim(),nodes:[]};state.studyBoards.unshift(b);state.currentBoardId=b.id;persist();closeModal();setPage('study');toast('Study canvas created.');}
  });
  document.addEventListener('change',e=>{
    const t=e.target;
    if(t.id==='book-select'){state.reader.book=t.value;state.reader.chapter=chaptersFor(t.value)[0];state.reader.selectedVerse=1;persist();renderBible();}
    if(t.id==='chapter-select'){state.reader.chapter=Number(t.value);state.reader.selectedVerse=1;persist();renderBible();}
    if(t.id==='font-size'){state.preferences.fontSize=Number(t.value);persist();}
    if(t.id==='annotation-color'){annotationColor=t.value;}
    if(t.id==='annotation-width'){annotationWidth=Number(t.value);}
    if(t.id==='journal-filter'){renderJournal();}
    if(t.id==='board-select'){state.currentBoardId=t.value;persist();renderStudy();}
    if(t.id==='name-setting'){state.name=t.value.trim();persist();toast('Name saved.');}
    if(t.id==='theme-setting'){state.preferences.theme=t.value;persist();renderCurrent();}
    if(t.id==='font-setting'){state.preferences.fontSize=Number(t.value);persist();renderSettings();}
    if(t.id==='spacing-setting'){state.preferences.lineHeight=Number(t.value);persist();renderSettings();}
    if(t.id==='reminder-setting'){state.preferences.reminder=t.value;persist();toast(t.value?'Reminder time saved.':'Reminder time cleared.');}
    if(t.matches('[data-action="goal-toggle"]')){const g=state.goals.find(x=>x.id===t.dataset.id);if(g){g.done=t.checked;persist();}}
  });
  document.addEventListener('input',e=>{if(e.target.id==='journal-search'){searchQuery=e.target.value;const pos=e.target.selectionStart;renderJournal();const el=$('#journal-search');el?.focus();el?.setSelectionRange(pos,pos);}});
  document.addEventListener('keydown',e=>{
    if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openSearch();}
    if(e.key==='Escape'&&!$('#modal-backdrop').hidden)closeModal();
    if(e.target.matches('.verse-row')&&(e.key==='Enter'||e.key===' ')){e.preventDefault();e.target.click();}
  });
  function copyVerse(ref) {const p=parseReference(ref),txt=p?`${verseText(p.book,p.chapter,p.verse)} — ${ref} (${DATA.translation})`:'';if(!txt)return; navigator.clipboard?.writeText(txt).then(()=>toast('Verse copied to clipboard.')).catch(()=>fallbackCopy(txt)); }
  function fallbackCopy(text){const area=document.createElement('textarea');area.value=text;document.body.append(area);area.select();document.execCommand('copy');area.remove();toast('Verse copied to clipboard.');}
  async function shareVerse(ref){const p=parseReference(ref),text=p?`${verseText(p.book,p.chapter,p.verse)} — ${ref} (${DATA.translation})`:'';if(!text)return;if(navigator.share){try{await navigator.share({title:'E-Journal Bible',text});}catch{}}else openModal(`<span class="eyebrow">SHARE SCRIPTURE</span><h2 id="modal-title">A verse to share</h2><div class="share-card"><p>“${esc(verseText(p.book,p.chapter,p.verse))}”</p><small>${esc(ref.toUpperCase())} · ${esc(DATA.translation)} · E-JOURNAL BIBLE</small></div><div class="modal-actions"><button class="btn secondary" data-action="modal-close">Close</button><button class="btn" data-action="copy" data-ref="${esc(ref)}">Copy verse</button></div>`);}
  $('#menu-toggle').addEventListener('click',()=>$('#sidebar').classList.toggle('open'));
  $('#global-search-open').addEventListener('click',openSearch);
  $('#profile-shortcut').addEventListener('click',()=>setPage('settings'));
  $('#modal-close').addEventListener('click',closeModal);$('#modal-backdrop').addEventListener('click',e=>{if(e.target.id==='modal-backdrop')closeModal();});
  $('#import-file').addEventListener('change',e=>{if(e.target.files?.[0])importData(e.target.files[0]);e.target.value='';});
  window.addEventListener('storage',e=>{if(e.key===KEY){state=loadState();renderCurrent();}});
  // available-chapter navigation is based on the chapters in the local corpus
  document.addEventListener('click',e=>{const b=e.target.closest('[data-action="chapter-prev"],[data-action="chapter-next"]');if(!b)return;const pairs=knownRefs().map(x=>`${x.book}|${x.chapter}`).filter((x,i,a)=>a.indexOf(x)===i);let i=pairs.indexOf(`${state.reader.book}|${state.reader.chapter}`);i+=b.dataset.action==='chapter-prev'?-1:1;const [book,ch]=pairs[i].split('|');state.reader={book,chapter:Number(ch),selectedVerse:1};persist();renderBible();});
  // study cards can be moved by mouse, touch, or pen
  document.addEventListener('pointerdown',e=>{const node=e.target.closest('.board-node');if(!node||e.target.closest('button'))return;const b=boardById(),n=b?.nodes.find(x=>x.id===node.dataset.node);if(!n)return;dragNode={node,n,startX:e.clientX,startY:e.clientY,left:n.x||0,top:n.y||0};node.setPointerCapture?.(e.pointerId);});
  document.addEventListener('pointermove',e=>{if(!dragNode)return;const dx=e.clientX-dragNode.startX,dy=e.clientY-dragNode.startY;dragNode.n.x=Math.max(0,dragNode.left+dx);dragNode.n.y=Math.max(0,dragNode.top+dy);dragNode.node.style.left=`${dragNode.n.x}px`;dragNode.node.style.top=`${dragNode.n.y}px`;});
  document.addEventListener('pointerup',()=>{if(dragNode){persist();dragNode=null;}});
  document.addEventListener('dblclick',e=>{const node=e.target.closest('.board-node');if(!node||e.target.closest('button'))return;const b=boardById(),n=b?.nodes.find(x=>x.id===node.dataset.node);if(n){const text=prompt('Edit this card',n.text);if(text!==null){n.text=text;persist();renderStudy();}}});
  applyPreferences();
  setPage(state.page||'home');
})();
